-- =====================================================
-- 08. POPULATE CLIENTCUSTOMERDATA TABLE
-- =====================================================
-- ClientCustomerData stores all customer account information
-- for ScalePoint's 750 customer accounts (150 Enterprise, 
-- 300 Mid-Market, 300 SMB)
--
-- This includes account details, financial data, usage metrics,
-- health scores, and customer success information
--
-- Must be inserted AFTER ClientTeam table is populated
-- =====================================================

INSERT INTO "ClientCustomerData" (
