-- =====================================================
-- VERIFICATION QUERIES
-- =====================================================

-- Count by account type
SELECT 
  account_type,
  COUNT(*) as account_count,
  SUM(arr) as total_arr,
  AVG(arr) as avg_arr,
  AVG(overall_health_score) as avg_health_score
FROM "ClientCustomerData"
WHERE client_id = (SELECT client_id FROM "Clients" WHERE slug = 'scalepoint')
GROUP BY account_type
ORDER BY account_type;

-- Count by CSM
SELECT 
  assigned_csm_id,
  COUNT(*) as account_count,
  SUM(arr) as total_portfolio_arr,
  AVG(overall_health_score) as avg_health_score,
  COUNT(*) FILTER (WHERE risk_level = 'High' OR risk_level = 'Critical') as at_risk_count
FROM "ClientCustomerData"
WHERE client_id = (SELECT client_id FROM "Clients" WHERE slug = 'scalepoint')
GROUP BY assigned_csm_id
ORDER BY assigned_csm_id;

-- Health score distribution
SELECT 
  CASE 
    WHEN overall_health_score >= 80 THEN 'Healthy (80-100)'
    WHEN overall_health_score >= 60 THEN 'Moderate (60-79)'
    WHEN overall_health_score >= 40 THEN 'At Risk (40-59)'
    ELSE 'Critical (<40)'
  END as health_category,
  COUNT(*) as account_count,
  SUM(arr) as total_arr
FROM "ClientCustomerData"
WHERE client_id = (SELECT client_id FROM "Clients" WHERE slug = 'scalepoint')
GROUP BY health_category
ORDER BY MIN(overall_health_score) DESC;

-- Top 10 accounts by ARR
SELECT 
  account_id,
  account_name,
  account_type,
  industry,
  arr,
  overall_health_score,
  assigned_csm_id
FROM "ClientCustomerData"
WHERE client_id = (SELECT client_id FROM "Clients" WHERE slug = 'scalepoint')
ORDER BY arr DESC
LIMIT 10;

-- Summary statistics
SELECT 
  COUNT(*) as total_accounts,
  SUM(arr) as total_arr,
  AVG(arr) as avg_arr,
  AVG(overall_health_score) as avg_health_score,
  COUNT(*) FILTER (WHERE risk_level IN ('High', 'Critical')) as at_risk_accounts,
  SUM(arr) FILTER (WHERE risk_level IN ('High', 'Critical')) as at_risk_arr,
  COUNT(*) FILTER (WHERE expansion_potential_score >= 70) as expansion_ready
FROM "ClientCustomerData"
WHERE client_id = (SELECT client_id FROM "Clients" WHERE slug = 'scalepoint');

-- =====================================================
-- NOTES
-- =====================================================
-- This populates 750 customer accounts for ScalePoint:
-- - 150 Enterprise accounts (avg $2-5M ARR each)
-- - 300 Mid-Market accounts (avg $100K-500K ARR each)
-- - 300 SMB accounts (avg $10K-50K ARR each)
--
-- Accounts are distributed across 45 CSMs:
-- - 30 Enterprise CSMs managing 5 accounts each
-- - 10 Mid-Market CSMs managing 30 accounts each
-- - 5 SMB CSMs managing 60 accounts each
--
-- Data includes comprehensive metrics:
-- ✅ Financial: ARR, MRR, contract details, payment status
-- ✅ Usage: Active users, feature adoption, integrations
-- ✅ Health: Overall score and component scores
-- ✅ Risk: Churn probability, risk level, at-risk revenue
-- ✅ Expansion: Opportunity scores and projected value
-- ✅ Support: Ticket counts, resolution times, SLA compliance
-- ✅ Engagement: NPS, CSAT, meetings, communication frequency
